e.on('error', () => console.log(1))
e.emit('error', new Error('x'))
console.log(2)

const { EventEmitter } = require('events')
const e = new EventEmitter()
EventEmitter.once(e, 'x').then(([n]) => console.log(n))
e.emit('x', 5)

setImmediate(() => {
  process.nextTick(() => console.log(1))
  console.log(2)
})

