const { MessageChannel } = require('worker_threads')
const { port1, port2 } = new MessageChannel()
port1.on('message', (n) => console.log(n))
port2.postMessage(4)

const { Transform } = require('stream')
let n = 0
const t = new Transform({
  transform(chunk, _enc, cb) {
    n += 1
    cb(null, chunk)
  },
  flush(cb) {
    console.log(n)
    cb()
  },
})
t.on('data', () => {})
t.write('a')
t.write('b')
t.end()

const { Readable } = require('stream')
const r = Readable.from([Buffer.from('x')])
r.on('end', () => console.log(1))
r.on('data', () => console.log(2))

const { Buffer: B } = require('buffer')
console.log(B.isBuffer(B.from('a')) ? 1 : 0)
console.log(B.isBuffer(Uint8Array.from([1])) ? 1 : 0)

