console.log(types.isSet(new Set()) ? 1 : 0)
console.log(types.isSet([]) ? 1 : 0)

const { EventEmitter } = require('events')
const e = new EventEmitter()
e.on('x', () => console.log(1))
e.on('x', () => {
  throw new Error('boom')
})
e.on('x', () => console.log(2))
try {
  e.emit('x')
} catch {
  console.log(3)
}

const { pipeline, Readable, Writable } = require('stream')
let n = 0
const dest = new Writable({
  write(chunk, _enc, cb) {
    n += Number(chunk)
    cb()
  },
})
pipeline(Readable.from(['1', '2']), dest, (err) => {
  console.log(err ? 0 : n)
})
